  const val=v.valuesByMode[col.modes[0].modeId];
  return {id:v.id,name:v.name,col:col.name,type:v.resolvedType,val:(val&&val.r!==undefined)?[val.r,val.g,val.b].map(x=>+x.toFixed(2)):val};
});
