bak.x = set.x; bak.y = set.y + set.height + 80;
// 2) 변수
const V = {n100:'VariableID:5003:11070',n200:'VariableID:5003:11064',n300:'VariableID:5003:11061',n400:'VariableID:5003:11063',n1000:'VariableID:5003:11071',w:'VariableID:5003:11068',lime:'VariableID:3003:11991'};
const vars={}; for(const k in V) vars[k]=await figma.variables.getVariableByIdAsync(V[k]);
const P=(k)=>[figma.variables.setBoundVariableForPaint({type:'SOLID',color:{r:0,g:0,b:0}},'color',vars[k])];
const add=(p,n,k,x,y,w,h,r)=>{n.fills=P(k);n.resize(w,h);if(r!==undefined&&'cornerRadius' in n)n.cornerRadius=r;p.appendChild(n);n.x=x;n.y=y;return n;};
const rect=(p,k,x,y,w,h,r)=>add(p,figma.createRectangle(),k,x,y,w,h,r);
const ell=(p,k,x,y,w,h)=>add(p,figma.createEllipse(),k,x,y,w,h);
const tri=(p,k,x,y,w,h,r)=>{const t=figma.createPolygon();t.pointCount=3;return add(p,t,k,x,y,w,h,r);};
const rot45=(n,cx,cy,s)=>{const c=Math.SQRT1_2;n.relativeTransform=[[c,-c,cx],[c,c,cy-s*c]];};
const xbadge=(p,x,y,d)=>{ell(p,'n1000',x,y,d,d);const L=d*0.5,T=3;for(const a of [1,-1]){const r=rect(p,'w',0,0,L,T,2);const c=Math.SQRT1_2*a;r.relativeTransform=[[Math.SQRT1_2,-Math.SQRT1_2*a*-1*0+ (a===1?-Math.SQRT1_2:Math.SQRT1_2),0],[Math.SQRT1_2*(a===1?1:-1),Math.SQRT1_2,0]];
  // 중심 정렬
  const cx=x+d/2, cy=y+d/2; const m=r.relativeTransform; r.relativeTransform=[[m[0][0],m[0][1],cx-(m[0][0]*L/2+m[0][1]*T/2)],[m[1][0],m[1][1],cy-(m[1][0]*L/2+m[1][1]*T/2)]];}};
const build={};
build['Cloud']=p=>{rect(p,'n200',8,38,80,36,18);ell(p,'n200',20,22,36,36);ell(p,'n200',42,14,40,40);rect(p,'n300',8,64,80,10,5);ell(p,'lime',58,52,32,32);rect(p,'n1000',72,58,4,12,2);ell(p,'n1000',72,74,4,4);};
build['Connection Error']=p=>{const arc=(k,s,ir)=>{const e=ell(p,k,48-s/2,66-s/2,s,s);e.arcData={startingAngle:-3*Math.PI/4,endingAngle:-Math.PI/4,innerRadius:ir};};arc('n200',84,0.82);arc('n300',58,0.74);arc('n400',32,0.5);ell(p,'lime',40,58,16,16);xbadge(p,62,52,28);};
build['No Picture']=p=>{rect(p,'n200',8,14,80,68,16);rect(p,'w',14,20,68,56,11);ell(p,'lime',54,28,16,16);tri(p,'n300',18,48,38,26,4);tri(p,'n400',38,42,40,32,4);xbadge(p,62,56,28);};
build['Empty Folder']=p=>{rect(p,'n300',10,20,76,56,12);rect(p,'n300',10,14,34,16,8);rect(p,'n200',10,32,76,44,12);ell(p,'lime',44,40,34,34);ell(p,'w',50,46,22,22);const h=rect(p,'n1000',0,0,18,6,3);h.rotation=-45;h.x=70;h.y=70;};
build['Empty Mail']=p=>{const f=figma.createFrame();f.fills=[];f.clipsContent=true;f.resize(76,50);f.cornerRadius=12;p.appendChild(f);f.x=10;f.y=28;rect(f,'n200',0,0,76,50,0);const d=rect(f,'n300',0,0,34,34,7);rot45(d,38,6,34);ell(p,'lime',58,54,28,28);rect(p,'n1000',64,66,16,4,2);};
build['No Content']=p=>{rect(p,'n300',20,12,60,66,12);rect(p,'n200',12,22,64,62,12);rect(p,'w',22,36,26,6,3);rect(p,'w',22,48,42,6,3);rect(p,'lime',22,62,22,10,5);};
build['No Notification']=p=>{ell(p,'n300',28,12,40,40);rect(p,'n300',22,34,52,32,10);rect(p,'n400',14,58,68,10,5);ell(p,'n1000',38,70,20,14);ell(p,'lime',58,8,24,24);};
const done=[];
for(const c of set.children){
  const key=c.name.replace('Property 1=','');
  if(!build[key]) {done.push({key,skip:true});continue;}
  for(const ch of [...c.children]) ch.remove();
  c.clipsContent=true;
  build[key](c);
  done.push({key,id:c.id,n:c.children.length});
}
return {backup:bak.id,done};

