const tpl = await figma.getNodeByIdAsync('5013:27194');
await figma.setCurrentPageAsync(tpl);
const CAM='11845:59610', DEX='11997:83897', AI='12119:84601';
const plan = [
 ['11957:51357','도감으로 돌아가기',DEX],
 ['11957:51441','촬영하러 가기',CAM],
 ['11957:51537','홈으로 가기',DEX],
 ['11957:51626','첫 포착하러 가기',CAM],
 ['11957:51722','질문하기',AI],
 ['11959:17216','첫 포착하러 가기',CAM],
 ['11959:17279','Live로 촬영하기',CAM],
 ['11959:17398','다시 촬영하기',CAM],
 ['11959:17501','도감으로 가기',DEX],
];
const res=[];
for(const [fid,label,dest] of plan){
  const f=await figma.getNodeByIdAsync(fid);
  const d=await figma.getNodeByIdAsync(dest);
  if(!f||!d){res.push({fid,err:'missing',dest:!!d});continue;}
  const t=f.findOne(n=>n.type==='TEXT'&&n.characters===label);
  if(!t){res.push({fid,err:'no text'});continue;}
  let b=t.parent; while(b&&b!==f&&!(b.type==='INSTANCE'||b.type==='COMPONENT')) b=b.parent;
  if(!b||b===f){b=t.parent;}
  await b.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:null,preserveScrollPosition:false}]}]);
  res.push({fid,label,btn:b.id,btnType:b.type,dest,destName:d.name,destParent:d.parent&&d.parent.type});
}
return res;

