 ['P-01 탐험맵 · 준비 중','탐험맵을 준비하고 있어요','곧 새로운 모습으로 만나요','도감으로 가기','Empty Folder'],
 ['P-02 설정 · 준비 중','설정 화면을 준비하고 있어요','알림·계정 설정이 여기에 들어가요','돌아가기','No Content'],
 ['P-03 도감 · 분류 필터 결과 · 준비 중','분류별 도감을 준비하고 있어요','선택한 분류의 생물이 여기에 모여요','돌아가기','Empty Folder'],
 ['P-04 이름 후보 · 다른 항목 선택 · 준비 중','이름 후보 화면을 준비하고 있어요','다른 후보를 고르는 화면이에요','돌아가기','No Content'],
 ['P-05 검색 · 입력 중 · 준비 중','검색 화면을 준비하고 있어요','입력한 검색어 결과가 여기에 보여요','돌아가기','No Content'],
 ['P-06 척척박사 · 질문 입력 · 준비 중','질문 입력 화면을 준비하고 있어요','척척박사에게 물어보는 화면이에요','돌아가기','No Content'],
];
const out=[]; let x=80;
for(const [name,title,sub,btn,variant] of defs){
  const f=src.clone(); sec.appendChild(f); f.name=name; f.x=x; f.y=160; x+=453;
  const texts=f.findAll(n=>n.type==='TEXT');
  const m={'페이지를 찾을 수 없어요':title,'주소가 바뀌었거나 삭제된 기록이에요':sub,'도감으로 돌아가기':btn};
  for(const t of texts){ if(m[t.characters]!==undefined){ const segs=t.getStyledTextSegments(['fontName']); for(const s of segs) await figma.loadFontAsync(s.fontName); t.characters=m[t.characters]; } }
  const g=f.findOne(n=>n.type==='INSTANCE'&&n.name==='Empty-graphic');
  if(g){ try{ g.setProperties({'Property 1':variant}); }catch(e){ const set=g.mainComponent.parent; const v=set.children.find(c=>c.name==='Property 1='+variant); if(v) g.swapComponent(v);} }
  const top=f.children.map(c=>c.id+' '+c.name+' '+c.type);
  out.push({id:f.id,name,top});
}
sec.resizeWithoutConstraints(x-80+160, 852+320);
return {sec:sec.id,out};

