input.code:
const tpl = await figma.getNodeByIdAsync('5013:27194');
await figma.setCurrentPageAsync(tpl);
const DEX='11997:83897', P1='12311:99870', P2='12311:99921', P3='12311:99971', P4='12311:100022', P5='12311:100072', P6='12311:100122', SEARCH='12115:83919';
const log={tab:0,gear:0,search:0,chip:0,cand:0,field:0,more:0,ph:[],skipped:[]};
const nav=(dest)=>[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:null,preserveScrollPosition:false}]}];
const back=()=>[{trigger:{type:'ON_CLICK'},actions:[{type:'BACK'}]}];
// 1) 임시 화면
for(const [id,toDex] of [[P1,true],[P2],[P3],[P4],[P5],[P6]]){
  const f=await figma.getNodeByIdAsync(id);
  const sa=f.findOne(n=>n.name==='safe area');
  const cand=f.findAll(n=>n.type==='INSTANCE'&&n.reactions.length===0&&n.visible);
  const btn=cand.find(n=>/Button/i.test(n.name)&&n.findOne(t=>t.type==='TEXT'&&/돌아가기|도감으로/.test(t.characters)));
  const bk=cand.find(n=>/leading|back|navigation|chevron|arrow|icon/i.test(n.name)&&n.y<120&&n.width<80);
  if(btn) await btn.setReactionsAsync(toDex?nav(DEX):back());
  if(bk) await bk.setReactionsAsync(back());
  log.ph.push({id,btn:btn&&btn.id,bk:bk&&bk.name});
}
// 2) 흐름 화면
const secs = tpl.children.filter(s=>s.type==='SECTION'&&/^[Ⓐ-Ⓖ]/.test(s.name));
const frames=[]; for(const s of secs) for(const f of s.children) if('findAll' in f) frames.push(f);
const txt=(n)=>n.findAll?n.findAll(t=>t.type==='TEXT').map(t=>t.characters).join('|'):'';
for(const f of frames){
  const all=f.findAll(()=>true);
  for(const n of all){
    if(!('reactions' in n)||n.reactions.length||!n.visible) continue;
    if(n.type==='INSTANCE'&&/^Tab Bar Button/.test(n.name)){
      const t=txt(n);
      if(t==='도감'){await n.setReactionsAsync(nav(DEX));log.tab++;}
      else if(/탐험/.test(t)){await n.setReactionsAsync(nav(P1));log.tab++;}
    } else if(n.type==='INSTANCE'&&/^settings-filled$/.test(n.name)){await n.setReactionsAsync(nav(P2));log.gear++;}
    else if(n.type==='INSTANCE'&&/^search-filled$/.test(n.name)&&/^C-01/.test(f.name)){await n.setReactionsAsync(nav(SEARCH));log.search++;}
    else if(n.type==='INSTANCE'&&/^Chip-item$/.test(n.name)&&/^C-01/.test(f.name)&&txt(n)!=='전체'){await n.setReactionsAsync(nav(P3));log.chip++;}
    else if(/Name Candidate Row/.test(n.name)){await n.setReactionsAsync(nav(P4));log.cand++;}
    else if(n.name==='Search Field'&&/^C-14/.test(f.name)){await n.setReactionsAsync(nav(P5));log.field++;}
  }
  // ⋯ 탐험맵에서 보기
  if(/^C-09/.test(f.name)){
    const t=f.findOne(x=>x.type==='TEXT'&&/탐험맵에서 보기|탐험 맵에서 보기/.test(x.characters));
    if(t){let r=t.parent;while(r&&r!==f&&!(r.type==='INSTANCE'||/Row|Item|Cell/.test(r.name)))r=r.parent; if(r&&r!==f){await r.setReactionsAsync(nav(P1));log.more++;}}
  }
}
// 척척박사 입력 후보 탐색 (연결은 찾은 것만)
const aiFrames=frames.filter(f=>/^C-19/.test(f.name));
log.ai=aiFrames.map(f=>({f:f.name,hits:f.findAll(n=>/input|입력|Chat Input|TextField|Message ?Field|composer/i.test(n.name)&&n.visible).slice(0,4).map(n=>n.id+' '+n.name+' '+n.type+' r'+n.reactions?.length)}));
return log;

