const backR=[{trigger:{type:'ON_CLICK'},actions:[{type:'BACK'}]}];
const topOf=(n)=>{let p=n;while(p.parent&&p.parent.type!=='SECTION'&&p.parent.type!=='PAGE')p=p.parent;return p;};
const log={ok:0,err:[]};
