// A-09 약관 행
const a9=await figma.getNodeByIdAsync('11942:53782');
for(const [txt,dest] of [['회원 이용약관','11942:55110'],['개인정보 수집/이용','11942:55111']]){
  const t=a9.findOne(x=>x.type==='TEXT'&&x.visible&&x.characters===txt); if(!t){log.err.push('no '+txt);continue;}
  let p=t.parent; while(p&&p!==a9&&p.reactions.length===0&&p.parent!==a9&&!(p.type==='INSTANCE')) p=p.parent;
  // 행 전체(텍스트+화살표) 단위: 텍스트의 부모가 Row 계열이면 그걸, 아니면 텍스트 부모
  let row=t.parent; while(row.parent&&row.parent!==a9&&row.width<300) row=row.parent;
  await setR(row.width>=300?row:t.parent,navR(dest));
