for(const id of ['11942:55110','11942:55111']){const f=await figma.getNodeByIdAsync(id);const b=f.findOne(n=>n.name==='Leading Button'&&n.reactions.length===0);if(b)await setR(b,backR);else log.err.push('nolb '+id);}
// 메달 → 뱃지 팝업
const d08=await figma.getNodeByIdAsync('12159:100097'); let medal=0;
for(const m of d08.findAll(n=>n.visible&&n.type==='INSTANCE'&&/ · /.test(n.name)&&n.width>100&&n.width<130&&n.height>150&&n.reactions.length===0)){await setR(m,navR('12210:85515'));medal++;}
log.medal=medal;
