for(const id of ['12001:222643','12158:100194']){const f=await figma.getNodeByIdAsync(id);const t=f.findOne(x=>x.type==='TEXT'&&x.visible&&/연속 방문/.test(x.characters));
 if(t){let p=t.parent;while(p&&p!==f&&!(p.width>=150&&p.width<393&&p.height>=40))p=p.parent; if(p&&p!==f){ if(p.reactions.length===0)await setR(p,navR('12210:85899')); else log['att'+id]='has '+p.name;}}}
// B-06 앨범 구조 파악
const alb=await figma.getNodeByIdAsync('11796:72825');
const cont=alb.findOne(n=>/Content/.test(n.name));
log.albKids=cont.children.map(c=>c.name+' '+c.type+' '+Math.round(c.width)+'x'+Math.round(c.height)+' @'+Math.round(c.x)+','+Math.round(c.y));
// 시작점 재계산: 기존 14개만 남기고 필요한 것만 추가
const orig=tpl.flowStartingPoints.slice(0,14);
const names=/^[Ⓐ-Ⓖ]|^빈껍데기|Empty State/;
const frames=[]; for(const s of tpl.children) if(s.type==='SECTION'&&names.test(s.name)) for(const f of s.children) if('findAll' in f) frames.push(f);
const out=new Map();
for(const f of frames){const set=new Set();for(const n of [f,...f.findAll(()=>true)]){if(!('reactions' in n))continue;for(const r of n.reactions)for(const a of (r.actions||[]))if(a&&a.destinationId)set.add(a.destinationId);}out.set(f.id,set);}
const seenS=new Set(orig.map(p=>p.nodeId)); const q=[...seenS];
while(q.length){const id=q.shift();const s=out.get(id);if(!s)continue;for(const d of s)if(!seenS.has(d)){seenS.add(d);q.push(d);}}
const add=[];
for(const f of frames){ if(seenS.has(f.id))continue; add.push({nodeId:f.id,name:f.name}); const q2=[f.id]; seenS.add(f.id); while(q2.length){const id=q2.shift();const s=out.get(id);if(!s)continue;for(const d of s)if(!seenS.has(d)){seenS.add(d);q2.push(d);}} }
const used=new Set(orig.map(p=>p.name)); for(const a of add){let n=a.name,i=2;while(used.has(n))n=a.name+' ('+(i++)+')';a.name=n;used.add(n);}
tpl.flowStartingPoints=[...orig,...add];
log.starts=add.map(a=>a.name);
return log;

