const tpl = await figma.getNodeByIdAsync('5013:27194');
await figma.setCurrentPageAsync(tpl);
const navR=(d)=>[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:d,navigation:'NAVIGATE',transition:null,preserveScrollPosition:false}]}];
const log={err:[]};
const src=await figma.getNodeByIdAsync('11997:83897');
const oldP3=await figma.getNodeByIdAsync('12311:99971');
const sec=await figma.getNodeByIdAsync('12311:99869');
const c=src.clone(); sec.appendChild(c); c.name='C-01b 도감 · 조류 필터 결과'; c.x=oldP3.x; c.y=oldP3.y;
// 칩 상태
const chips=c.findAll(n=>n.type==='INSTANCE'&&n.name==='Chip-item');
for(const ch of chips){const t=ch.findOne(x=>x.type==='TEXT').characters; try{ch.setProperties({State:t==='조류'?'active':'default'});}catch(e){log.err.push('chip '+t+' '+e.message.slice(0,50));}}
// 컬렉션: 조류 그룹만
const coll=c.findOne(n=>n.type==='INSTANCE'&&n.name==='Collection');
let shown=0,hidden=0;
for(const g of coll.children){const has=g.findAll?g.findAll(t=>t.type==='TEXT'&&t.characters==='조류').length>0:false; if(has){g.visible=true;shown++;}else{g.visible=false;hidden++;}}
log.coll={shown,hidden,kids:coll.children.length,h:Math.round(coll.height)};
// 칩 반응: 전체/다른 분류 → C-01
for(const ch of chips){const t=ch.findOne(x=>x.type==='TEXT').characters; if(t!=='조류'){await ch.setReactionsAsync(navR('11997:83897'));} else await ch.setReactionsAsync([]);}
// 기존 C-01류 칩 → 새 필터 화면
let rewired=0;
const secs=tpl.children.filter(s=>s.type==='SECTION'&&/^Ⓒ/.test(s.name));
for(const s of secs) for(const f of s.children){ if(!('findAll' in f)) continue; if(f.id===c.id) continue; if(!/^C-01/.test(f.name)) continue;
  for(const ch of f.findAll(n=>n.type==='INSTANCE'&&n.name==='Chip-item'&&n.reactions.length&&n.reactions[0].actions[0]&&n.reactions[0].actions[0].destinationId==='12311:99971')){
    const t=ch.findOne(x=>x.type==='TEXT').characters; await ch.setReactionsAsync(navR(c.id)); rewired++; }}
log.rewired=rewired;
// 이름 후보 행: 선택 상태 → 연결 제거
let cand=0; for(const n of tpl.findAll(x=>/Name Candidate Row/.test(x.name)&&x.reactions&&x.reactions.length)){ if(n.reactions[0].actions[0]&&n.reactions[0].actions[0].destinationId==='12311:100022'){await n.setReactionsAsync([]);cand++;}} log.cand=cand;
// 검색창: C-14a → 결과, C-14b/c → 입력
const sf=async(fid,dest)=>{const f=await figma.getNodeByIdAsync(fid);const n=f.findOne(x=>x.name==='Search Field');if(n){await n.setReactionsAsync(navR(dest));}else log.err.push('nosf '+fid);};
await sf('12115:83919','12115:84003'); await sf('12115:84003','12115:83919'); await sf('12115:84076','12115:83919');
// 척척박사 입력
for(const [id,d] of [['12119:84667','12119:84675'],['12119:84736','12119:84744']]){const n=await figma.getNodeByIdAsync(id); await n.setReactionsAsync(navR(d));}
// 임시 화면 정리 → 휴지통
const trash=await figma.getNodeByIdAsync('12280:128877');
for(const id of ['12311:99971','12311:100022','12311:100072','12311:100122']){const n=await figma.getNodeByIdAsync(id); trash.appendChild(n); n.x=trash.width-500; n.y=0; n.name='[보관] '+n.name;}
log.trashH=trash.height;
return {id:c.id,log};

