const tpl=await figma.getNodeByIdAsync('5013:27194'); await figma.setCurrentPageAsync(tpl);
const names=/^[Ⓐ-Ⓖ]|^신규 화면|Empty State/;
const frames=[]; for(const s of tpl.children) if(s.type==='SECTION'&&names.test(s.name)) for(const f of s.children) if('findAll' in f) frames.push(f);
const out=new Map();
for(const f of frames){const set=new Set();for(const n of [f,...f.findAll(()=>true)]){if(!('reactions' in n))continue;for(const r of n.reactions)for(const a of (r.actions||[]))if(a&&a.destinationId)set.add(a.destinationId);}out.set(f.id,set);}
const valid=new Set(frames.map(f=>f.id));
// 원래 14개 + 정리: 유효한 시작점만 유지하되, 이제 도달 가능한 변형은 제외하기 위해 핵심 시작점만 남김
const core=tpl.flowStartingPoints.slice(0,14).filter(p=>valid.has(p.nodeId));
const seen=new Set(core.map(p=>p.nodeId)); const q=[...seen];
while(q.length){const id=q.shift();const s=out.get(id);if(!s)continue;for(const d of s)if(!seen.has(d)){seen.add(d);q.push(d);}}
const add=[]; for(const f of frames){ if(seen.has(f.id))continue; add.push({nodeId:f.id,name:f.name}); const q2=[f.id];seen.add(f.id);while(q2.length){const id=q2.shift();const s=out.get(id);if(!s)continue;for(const d of s)if(!seen.has(d)){seen.add(d);q2.push(d);}}}
const used=new Set(core.map(p=>p.name)); for(const a of add){let n=a.name,i=2;while(used.has(n))n=a.name+' ('+(i++)+')';a.name=n;used.add(n);}
tpl.flowStartingPoints=[...core,...add];
return {core:core.map(p=>p.name),addedN:add.length,added:add.map(a=>a.name)};

