const imgSet=await figma.getNodeByIdAsync('3001:20264');
const phNone=imgSet.children.find(c=>c.name==='Type=img-placeholder, Radius Size=None');
const targets=['11997:77217','11997:77218','12016:104899','12001:225283','11913:62701','11932:65545','11932:65444','11932:65283','11958:57446','11939:48361','11942:53783','12001:219289','11997:76771','11997:76769','11997:76950','11899:52173','11845:59610','12125:78881'];
const res={replaced:0,nested:[],err:[]};
const inInstance=(n)=>{let p=n.parent;while(p&&p.type!=='PAGE'){if(p.type==='INSTANCE')return true;p=p.parent;}return false;};
for(const id of targets){const f=await figma.getNodeByIdAsync(id); if(!f)continue;
  const nodes=f.findAll(x=>(x.type==='RECTANGLE'||x.type==='FRAME')&&/^(Camera Image|IMG|img|photo-area|cutout-img)$/.test(x.name)&&Array.isArray(x.fills)&&x.fills.some(p=>p.type==='SOLID'&&p.boundVariables&&p.boundVariables.color&&p.boundVariables.color.id==='VariableID:5003:11064'));
  for(const n of nodes){
    if(inInstance(n)){res.nested.push(f.name.slice(0,14)+'/'+n.id);continue;}
    try{const par=n.parent; const idx=par.children.indexOf(n); const w=n.width,h=n.height,x=n.x,y=n.y;
      const inst=phNone.createInstance(); par.insertChild(idx,inst); inst.name='Image'; 
      const lp=n.layoutPositioning; if(lp==='ABSOLUTE')inst.layoutPositioning='ABSOLUTE';
      inst.resize(w,h);
      if(par.layoutMode&&par.layoutMode!=='NONE'&&lp!=='ABSOLUTE'){ if(n.layoutSizingHorizontal==='FILL')inst.layoutSizingHorizontal='FILL'; if(n.layoutSizingVertical==='FILL')inst.layoutSizingVertical='FILL'; if(n.layoutGrow)inst.layoutGrow=n.layoutGrow; } else {inst.x=x;inst.y=y;}
      try{inst.constraints=n.constraints;}catch(e){}
      if(typeof n.cornerRadius==='number'&&n.cornerRadius>0)inst.cornerRadius=n.cornerRadius;
      n.remove(); res.replaced++;}catch(e){res.err.push(n.id+' '+e.message.slice(0,60));}
  }}
return res;

