const add=[];
for(const f of frames){ if(seenS.has(f.id))continue; add.push({nodeId:f.id,name:f.name}); const q2=[f.id]; seenS.add(f.id); while(q2.length){const id=q2.shift();const s=out.get(id);if(!s)continue;for(const d of s)if(!seenS.has(d)){seenS.add(d);q2.push(d);}} }
const used=new Set(orig.map(p=>p.name)); for(const a of add){let n=a.name,i=2;while(used.has(n))n=a.name+' ('+(i++)+')';a.name=n;used.add(n);}
