const fonts=new Set();
for(const t of c.findAll(n=>n.type==='TEXT')) for(const s of t.getStyledTextSegments(['fontName'])) fonts.add(JSON.stringify(s.fontName));
for(const f of fonts) await figma.loadFontAsync(JSON.parse(f));
title.characters='일일 퀘스트 · 12개';
sub.characters='12개 가운데 매일 3개가 무작위로 주어져요. 1개를 끝낼 때마다 10 XP, 하루 최대 30 XP예요.';
const ruleRows=[
 ['뽑기','매일 0시에 풀에서 3개를 랜덤으로 준다. 같은 날 중복 없음 · 전날 나온 퀘스트 제외'],
 ['보상','1개 완료 10 XP · 하루 최대 30 XP'],
 ['수행 가능','지금 할 수 있는 퀘스트만 뽑는다 (예: 사진이 2장 없으면 대표 사진 고르기 제외)'],
 ['실내 보장','3개 중 실내에서 할 수 있는 퀘스트를 1개 이상 넣는다'],
 ['커뮤니티','커뮤니티 퀘스트는 2개 (탐험 메모 · 하트). 전체 풀의 1/3 이하'],
