const Q=[
 ['1','포착','오늘의 첫 포착','카메라로 생물 1번 포착 (등록 여부 무관)','10 XP'],
 ['2','포착','세 번 포착','오늘 카메라로 3번 포착','10 XP'],
 ['3','포착','새로운 종 발견','도감에 없던 종 1종 포착 (대기함 포함)','10 XP'],
