for(let i=rows.length-1;i>Q.length;i--) rows[i].remove();
const rr=quests.children;
Q.forEach((q,i)=>{ const cells=rr[i+1].children; q.forEach((v,j)=>{ T(cells[j]).characters=v; }); });
foot.characters='묶음별 개수: 포착 4 · 도감 3 · 탐험 1 · 기능 2 · 커뮤 2';
return {id:c.id,header,ruleLabels,remaining:quests.children.length,y:c.y};

