const pg = figma.root.children.find(p=>p.name==='레벨 디자인');
await figma.setCurrentPageAsync(pg);
const orig=await figma.getNodeByIdAsync('12465:117124');
const c=orig.clone();
c.name='L-01 레벨 · XP 체계 (v3)'; c.x=orig.x; c.y=orig.y+orig.height+300;
const fonts=new Set();
for(const t of c.findAll(n=>n.type==='TEXT')) for(const s of t.getStyledTextSegments(['fontName'])) fonts.add(JSON.stringify(s.fontName));
for(const f of fonts) await figma.loadFontAsync(JSON.parse(f));
const TX=n=>n.findAll(x=>x.type==='TEXT');
const set=(t,s)=>{ if(t) t.characters=s; };
const k=c.children, log=[];
const cum=n=>(n-1)*(5*n+20);
const fmt=n=>n.toLocaleString('en-US');
set(k[0],'레벨 · XP 체계 (v3)');
// 흐름 줄
for(const t of TX(k[2])){ if(t.characters.includes('브론즈')) set(t,'동 10 · 은 30 · 금 50 · 레전드 100 XP'); }
// 1. XP 표
const t4=k[4].children;
const badge=[['동 뱃지 획득','10 XP','동색 테두리 · 구성 미정'],['은 뱃지 획득','30 XP','은색 테두리 · 구성 미정'],['금 뱃지 획득','50 XP','금색 테두리 · 구성 미정'],['레전드 뱃지 획득','100 XP','무지개빛 테두리 · 구성 미정']];
badge.forEach((b,i)=>{ const tt=TX(t4[i+2]); const n=tt.length; set(tt[n-3],b[0]); set(tt[n-2],b[1]); set(tt[n-1],b[2]); });
set(k[5],'뱃지 개수 · 구성은 미정이에요 (정책 §11). 뱃지는 수집품이라 레벨 계산과 별개로 등급 XP만 줘요. 새 종 포착은 +30 XP (포착 10 + 새 종 20)예요.');
// 2. 레벨과 칭호
const t7=k[7].children;
const tiers=[['Lv.1 ~ 4',1,4,'약 9일'],['Lv.5 ~ 9',5,9,'약 23일'],['Lv.10 ~ 19',10,19,'약 82일'],['Lv.20 ~ 29',20,29,'약 133일'],['Lv.30 ~',30,null,'상한 없음 · 계속 오를 수 있어요']];
tiers.forEach((tr,i)=>{
 const tt=TX(t7[i+1]);
 set(tt[1],tr[0]);
 set(tt[2], tr[2]? ('레벨당 '+(10*tr[1]+20)+' ~ '+(10*tr[2]+10+0)+' XP') : ('레벨당 '+(10*tr[1]+20)+' XP ~'));
 set(tt[3],fmt(cum(tr[1]))+' XP');
 set(tt[4],tr[3]);
});
set(k[8],'포착 XP(새 종 +30)와 뱃지 XP가 더해지면 위 기간보다 빨라져요. 주 2종 + 퀘스트 하루 2개면 전설까지 약 5.7개월, 매일 1종 + 퀘스트 3개면 약 82일이에요.');
const t9=k[9].children;
tiers.forEach((tr,i)=>{
 const tt=TX(t9[i+1]); const end=tr[2]||(tr[1]+3); const arr=[];
 for(let n=tr[1];n<=end;n++) arr.push('Lv.'+n+'  '+fmt(cum(n)));
 set(tt[1],arr.join('   ·   ')+(tr[2]?'':'   ·   …'));
});
// 3. 칭호 표 머리글
const h=TX(k[11].children[0]);
['Lv.1 ~ 4','Lv.5 ~ 9','Lv.10 ~ 19','Lv.20 ~ 29','Lv.30 ~'].forEach((s,i)=>set(h[i+1],s));
// 4. 계산 예시
const ex=[
 ['온보딩 직후 (새 1종 포착)','포착 10 + 새 종 20 = 30 XP','Lv.2 새내기 조류 탐험가 · 다음 레벨까지 40 XP'],
 ['첫날 퀘스트 3개 완료','30 + 30 = 60 XP','Lv.2 새내기 조류 탐험가 · 다음 레벨까지 10 XP'],
 ['일주일 뒤 (퀘스트 21개 · 새 종 4종 · 동 뱃지 3개 더)','30 + 120 + 210 + 30 = 390 XP','Lv.7 관찰자 조류 탐험가 (180 XP에서 승급)'],
 ['한 달 뒤 (퀘스트 90개 · 새 종 20종 · 동 10 · 은 4 더)','600 + 900 + 100 + 120 = 1,720 XP','Lv.17 숙련가 조류 탐험가 (630 XP에서 승급)']
];
const t14=k[14].children;
ex.forEach((r,i)=>{ const tt=TX(t14[i+1]); r.forEach((s,j)=>set(tt[j],s)); });
// 5. 변경점
const t16=k[16].children;
for(const t of TX(t16[0])) if(t.characters==='v2') t.characters='v3';
{ const tt=TX(t16[1]); set(tt[tt.length-1],'누적 XP로 계산 (포착 + 퀘스트 + 뱃지)'); }
{ const tt=TX(t16[5]); set(tt[tt.length-1],'개수 미정, 등급은 금·은·동 테두리 색으로 표시 (등급별 XP 다름)'); }
// 확정 박스
const box=TX(k[17]);
set(box[0],'정책 확정 값 (2026-11-13)');
set(box[box.length-1],'· 뱃지 등급 XP: 동 10 · 은 30 · 금 50 · 레전드 100 (구성 · 개수 미정)\n· 칭호: 새내기 · 관찰자 · 숙련가 · 달인 · 전설 (경계 Lv 1 · 5 · 10 · 20 · 30)\n· 포착 XP: 새 종 +30, 같은 종 재포착 0 · 행동 보상은 퀘스트로만 (10 XP)');
// 전역 칭호 이름 치환
let rep=0;
for(const t of c.findAll(n=>n.type==='TEXT')){
 let s=t.characters, o=s;
 s=s.replace(/초보/g,'새내기').replace(/관찰하는/g,'관찰자').replace(/숙련된/g,'숙련가').replace(/마스터/g,'달인').replace(/전설의/g,'전설');
 if(s!==o){ t.characters=s; rep++; }
}
return {id:c.id,rep,t7:TX(t7[1]).length,tt14:TX(t14[1]).length,box:box.length,boxTexts:box.map(x=>x.characters.slice(0,30)),y:c.y};

