await figma.setCurrentPageAsync(pg);
const J=await figma.getNodeByIdAsync('12465:153455');
const exact={'+100':'없음','+5':'퀘스트','하루 20까지':'일일 퀘스트로 처리','하루 1회':'매일 3개 · 하루 최대 30','분류당 1회':'보상 없음','분류 세트 11개 완성':'분류 세트 완성','그날 첫 포착':'일일 퀘스트 완료','+10 / +30 / +60 / +150':'+10 / +30 / +50 / +100'};
const starts=[
 [/^· 뱃지 125개 = .*/, '· 뱃지 34개 = 공통 10 + 분류 7 × 3 + 균류 3 + 레전드 1. 수집품이며 레벨 계산에 들어가지 않는다'],
 [/^· 분류당 11개:.*/, '· 분류당 3개: 첫 발견(1종) · 베테랑(10종) · 마스터(30종). 균류는 1 · 5 · 10종'],
 [/^종 수 · 분류 세트 뱃지만.*/, '등급별 XP (동 10 · 은 30 · 금 50 · 레전드 100). 같은 종 재포착은 0'],
 [/^종마다 처음 S등급.*/, '한 컷 명품 퀘스트(90점 이상)로 대체. 매일 반복 가능'],
 [/^· 상태: 획득/, null]
];
const texts=J.findAll(n=>n.type==='TEXT');
const jobs=[];
for(const t of texts){
 const s=t.characters; let next=null;
 if(exact[s]!==undefined) next=exact[s];
 else for(const [re,rep] of starts){ if(rep!==null && re.test(s)) { next=rep; break; } }
 if(next!==null && next!==s) jobs.push([t,next,s]);
}
const fonts=new Set();
for(const [t] of jobs) for(const seg of t.getStyledTextSegments(['fontName'])) fonts.add(JSON.stringify(seg.fontName));
for(const f of fonts) await figma.loadFontAsync(JSON.parse(f));
for(const [t,next] of jobs) t.characters=next;
const left=J.findAll(n=>n.type==='TEXT').map(t=>t.characters).filter(s=>/125|11개|\+60|\+150|그날 첫|세트 11|\+100|20까지/.test(s));
return {changed:jobs.length, samples:jobs.slice(0,20).map(([t,n,o])=>o.slice(0,20)+' → '+n.slice(0,20)), leftover:left};

