const pg=figma.root.children.find(p=>p.name.includes('Components'));
await figma.setCurrentPageAsync(pg);
const created=[];
try{
const V=async id=>{ const v=await figma.variables.getVariableByIdAsync(id); if(!v) throw new Error('var missing '+id); return v; };
const [vMain,vFg,vBg,vDis,vLayer2,vWhite]=await Promise.all(['VariableID:12179:6996','VariableID:12179:6997','VariableID:12179:6998','VariableID:9131:1196','VariableID:3003:11981','VariableID:5003:11068'].map(V));
const cols=await figma.variables.getLocalVariableCollectionsAsync();
const tier=cols.find(c=>/Badge Tier/.test(c.name));
const bird=await figma.getNodeByIdAsync('11801:160600');
if(!bird) throw new Error('bird emoji missing');
const bind=(v)=>[figma.variables.setBoundVariableForPaint({type:'SOLID',color:{r:.6,g:.6,b:.6}},'color',v)];
// 홀로그램 페인트 스타일 (레전드 테두리)
let holo=(await figma.getLocalPaintStylesAsync()).find(s=>s.name==='Holo/Legend');
if(!holo){ holo=figma.createPaintStyle(); holo.name='Holo/Legend';
 holo.paints=[{type:'GRADIENT_LINEAR',gradientTransform:[[0.8,0.6,0],[-0.6,0.8,0.4]],gradientStops:[
  {position:0,color:{r:1,g:0.78,b:0.9,a:1}},{position:0.25,color:{r:0.7,g:0.88,b:1,a:1}},{position:0.5,color:{r:0.85,g:1,b:0.75,a:1}},{position:0.75,color:{r:1,g:0.9,b:0.65,a:1}},{position:1,color:{r:0.82,g:0.75,b:1,a:1}}]}]; }
const shieldPath=(w,h)=>`M 0 0 L ${w} 0 L ${w} ${h*0.58} Q ${w} ${h*0.88} ${w/2} ${h} Q 0 ${h*0.88} 0 ${h*0.58} Z`;
const makeShape=(kind,w,h)=>{
 if(kind==='circle'){ const e=figma.createEllipse(); e.resize(w,h); return e; }
 if(kind==='arch'){ const r=figma.createRectangle(); r.resize(w,h); r.topLeftRadius=w/2; r.topRightRadius=w/2; r.bottomLeftRadius=h*0.1; r.bottomRightRadius=h*0.1; return r; }
 if(kind==='shield'){ const v=figma.createVector(); v.vectorPaths=[{windingRule:'NONZERO',data:shieldPath(w,h)}]; return v; }
 const p=figma.createPolygon(); p.pointCount=6; p.resize(w,h); return p;
};
const grades=[
 {name:'동',  mode:'12179:0', kind:'circle', w:112,h:112, stars:1},
 {name:'은',  mode:'12179:1', kind:'arch',   w:100,h:112, stars:2},
 {name:'금',  mode:'12179:2', kind:'shield', w:100,h:116, stars:3},
 {name:'레전드',mode:'12179:3',kind:'hex',    w:112,h:112, stars:4}
];
const states=['Earned','Locked'];
const comps=[];
for(const g of grades){
 for(const st of states){
  const c=figma.createComponent(); c.name=`Grade=${g.name}, State=${st}`; c.resize(120,120); c.fills=[]; c.clipsContent=false;
  c.setExplicitVariableModeForCollection(tier,g.mode);
  const locked=st==='Locked';
  const rim=makeShape(g.kind,g.w,g.h); rim.name='Rim'; c.appendChild(rim);
  rim.x=(120-g.w)/2; rim.y=(120-g.h)/2;
  rim.fills=bind(locked?vDis:vMain);
  if(g.name==='레전드'&&!locked){ rim.fillStyleId=holo.id; }
  rim.effects=[{type:'DROP_SHADOW',color:{r:0,g:0,b:0,a:locked?0.06:0.2},offset:{x:0,y:3},radius:6,spread:0,visible:true,blendMode:'NORMAL'}];
  const fw=g.w*0.8, fh=g.h*0.8;
  const face=makeShape(g.kind,fw,fh); face.name='Face'; c.appendChild(face);
  face.x=(120-fw)/2; face.y=(120-fh)/2;
  face.fills=bind(locked?vLayer2:vBg);
  const emo=bird.createInstance(); emo.name='Emoji'; c.appendChild(emo);
  emo.resize(44,44); emo.x=38; emo.y=60-6-22; emo.opacity=locked?0.3:1;
  const row=figma.createAutoLayout('HORIZONTAL'); row.name='Stars'; row.itemSpacing=2; row.fills=[]; c.appendChild(row);
  for(let i=0;i<g.stars;i++){ const s=figma.createStar(); s.pointCount=5; s.innerRadius=0.4; s.resize(12,12); s.fills=bind(locked?vDis:vFg); row.appendChild(s); }
  row.x=(120-row.width)/2; row.y=60+fh/2-row.height-10;
  c.setExplicitVariableModeForCollection(tier,g.mode);
  comps.push(c); created.push(c.id);
 }
}
const set=figma.combineAsVariants(comps,pg);
set.name='Badge/Pin'; created.push(set.id);
// 그리드 배치: 열=상태, 행=등급
set.children.forEach(ch=>{
 const gi=grades.findIndex(g=>ch.name.includes('Grade='+g.name+',')); const si=ch.name.includes('State=Locked')?1:0;
 ch.x=24+si*152; ch.y=24+gi*152;
});
set.resize(24+2*152, 24+4*152);
set.fills=[]; set.strokes=[];
const key=set.addComponentProperty('Emoji','INSTANCE_SWAP',bird.id);
for(const ch of set.children){ const emo=ch.findOne(n=>n.name==='Emoji'&&n.type==='INSTANCE'); if(emo) emo.componentPropertyReferences={mainComponent:key}; }
set.description='업적 뱃지 그림. Grade(동·은·금·레전드)로 모양과 별 개수(1~4)가 정해지고, Emoji 속성으로 분류 이모지를 바꿉니다. Earned=획득, Locked=잠김. 색은 7. Badge Tier 모드(xp-10/30/50/100). 레전드는 Holo/Legend 스타일 테두리.';
// 위치: Components 페이지 오른쪽 빈 곳
let maxX=0; for(const ch of pg.children){ if(ch.id!==set.id) maxX=Math.max(maxX,ch.x+ch.width); }
set.x=maxX+400; set.y=0;
// 확인 프레임
const rev=figma.createAutoLayout('HORIZONTAL'); rev.name='Badge/Pin · 확인'; rev.itemSpacing=16; rev.paddingLeft=rev.paddingRight=rev.paddingTop=rev.paddingBottom=24; rev.fills=bind(vWhite); rev.cornerRadius=16;
for(const st of states){
 const col=figma.createAutoLayout('VERTICAL'); col.itemSpacing=16; col.fills=[]; rev.appendChild(col);
 for(const g of grades){ const v=set.children.find(c=>c.name===`Grade=${g.name}, State=${st}`); const inst=v.createInstance(); col.appendChild(inst); created.push(inst.id); }
}
rev.x=set.x+set.width+120; rev.y=0; created.push(rev.id);
return {setId:set.id,reviewId:rev.id,variants:set.children.length,propKey:key,pos:{x:set.x,y:set.y,w:set.width,h:set.height},rev:{w:rev.width,h:rev.height},holoStyleId:holo.id};
}catch(e){
 for(const id of created.reverse()){ try{ const n=await figma.getNodeByIdAsync(id); if(n) n.remove(); }catch(_){} }
 throw e;
}

